mapper.insert:
INSERT INTO shopping_cart_items (
    id, customer_id, product_id, sku, product_name, unit_price_cents,
    currency, quantity, created_at, updated_at
)
VALUES (
    #{id}, #{customerId}, #{productId}, #{sku}, #{productName}, #{unitPriceCents},
    #{currency}, #{quantity}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE shopping_cart_items
SET quantity = #{quantity}, updated_at = #{updatedAt}
WHERE customer_id = #{customerId} AND product_id = #{productId}

UPDATE shopping_cart_items
SET quantity = quantity - #{quantity}, updated_at = #{updatedAt}
WHERE customer_id = #{customerId}
  AND product_id = #{productId}
  AND quantity > #{quantity}

mapper.delete:
DELETE FROM shopping_cart_items
WHERE customer_id = #{customerId}
  AND product_id = #{productId}
  AND quantity = #{quantity}
